[TFMListElementAttribute('TFMListCustomComponentTrafficLight')]
class TFMListCustomComponentTrafficLight extends TFMListCustomComponent
{
    TFMListWidth	width;
    FieldName		fieldName;
    FieldValue		value1, value2, value3;

}

Method.Source:
[TFMParameter(100)]
public TFMListWidth parmwidth(TFMListWidth _width = width)
{
    width = _width;
    return width;
}

[TFMDataSourceParameter('')]
public FieldName parmFieldName(FieldName _fieldName = fieldName)
{
    fieldName = _fieldName;
    return fieldName;
}

[TFMDataSourceParameter('')]
public FieldValue parmRedLightValue(FieldValue _value1 = value1)
{
    value1 = _value1;
    return value1;
}

[TFMDataSourceParameter('')]
public FieldValue parmYellowLightValue(FieldValue _value2 = value2)
{
    value2 = _value2;
    return value2;
}

[TFMDataSourceParameter('')]
public FieldValue parmGreenLightValue(FieldValue _value3 = value3)
{
    value3 = _value3;
    return value3;
}

public Map SubComponents()
{
    Map					ReplacementElements = new Map(Types::Integer, Types::Class);
    TFMListImageElement	imageElement = new TFMListImageElement();

    imageElement.ParmSourceId('{trafficLightStatus}');
    imageElement.parmwidth(width);
    imageElement.parmHorizontalAlignment(SysChartHorizontalAlignment::Right);
    imageElement.parmVerticalAlignment(TFMVerticalAlignment::Top);
    ReplacementElements.insert(1, imageElement);
    return ReplacementElements;
}

public Set possibleParents()
{
    Set ret = super();
    ret.add('elements');
    return ret;
}

    public Map enrichDataset(Common _common, Map _existingMap)
    {
        Map				ret = super(_common,_existingMap);
        SysDictField	sdf = new SysDictField(_common.tableId,fieldName2Id(_common.tableId, fieldName));
        str				resStr = 'trafficlight_pct_';
        str				value;

		if (!sdf)
        {
            return ret;
        }

        value= strFmt('%1',_common.(sdf.id()));

		if ( value1 == value)
        {
            resStr += '0%';
        }
        else if ( value2 == value)
        {
            resStr += '50%';
        }
        else if (value3 == value)
        {
            resStr += '100%';
        }


		ret.insert('trafficLightStatus',resStr);

        return ret;
    }
